    {
        $builder->startVector(1, $numElems, 1);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endAPL(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // APL_ID
        $builder->required($o, 20);  // EXCEEDANCE_PERCENT
        $builder->required($o, 22);  // RAIN_LOSS_DB
        $builder->required($o, 24);  // GASEOUS_ABSORPTION_LOSS_DB
        $builder->required($o, 26);  // CLOUD_FOG_LOSS_DB
        $builder->required($o, 28);  // SCINTILLATION_LOSS_DB
        $builder->required($o, 30);  // TOTAL_LOSS_DB
        $builder->required($o, 32);  // XPD_DB
        $builder->required($o, 46);  // PROVENANCE
        $builder->required($o, 50);  // PRODUCER_ID
        $builder->required($o, 52);  // SIGNATURE
        $builder->required($o, 54);  // CANONICAL_JSON_SIGNATURE
        return $o;
    }

    public static function finishAPLBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$APL");
    }
